export interface ToolFaq {
  q: string;
  a: string;
}

export interface Tool {
  id: string;
  name: string;
  description: string;
  /** Custom meta description override. If omitted, createToolMetadata generates one from description. */
  metaDescription?: string;
  slug: string; // The URL path under /tools/[category]/[slug]
  categoryId: string;
  status: 'active' | 'planned';
  keywords?: string[];
  // Long-form SEO content (rendered below the tool UI)
  longDescription?: string;
  steps?: string[];
  useCases?: string[];
  faqs?: ToolFaq[];
  // IDs of related tools (rendered as a sidebar/footer rail)
  related?: string[];
}

export interface Category {
  id: string;
  name: string;
  description: string;
  longDescription?: string;
  keywords?: string[];
  faqs?: ToolFaq[];
}

